mapper.select:
SELECT COUNT(*) FROM VW_ACTIVE_PRODUCTS WHERE 1 = 1
AND PR_NAME LIKE CONCAT('%', #{searchKeyword}, '%')
AND PR_CATEGORY = #{pr_category}

SELECT COUNT(*) 
FROM VW_ACTIVE_PRODUCTS_COMMENTS 
WHERE PR_ID = #{pr_id}

SELECT * 
FROM VW_ACTIVE_PRODUCTS_COMMENTS 
WHERE PR_ID = #{pr_id} 


        ORDER BY PRC_RATING DESC, PRC_START_DATE DESC


        ORDER BY PRC_START_DATE DESC, PRC_NO DESC


        AND US_ID = #{us_id}
        ORDER BY PRC_START_DATE DESC, PRC_NO DESC


        ORDER BY PRC_NO DESC


LIMIT #{rowFirst}, #{rowSizePerPage}

SELECT COUNT(*) 
FROM VW_ACTIVE_PRODUCTS_COMMENTS 
WHERE PR_ID = #{pr_id} 
AND US_ID = #{us_id}

mapper.update:
UPDATE PRODUCTS_COMMENTS 
SET PRC_STATUS = "N"
WHERE PRC_NO = #{prc_no}

